function crearDoble() {
  const raiz = {};
  raiz.siguiente = raiz;
  raiz.anterior = raiz;
  return raiz;
}

function ponerAntes(destino, valor) {
  const nodo = { valor, anterior: destino.anterior, siguiente: destino };
  nodo.anterior.siguiente = nodo;
  destino.anterior = nodo;
  return nodo;
}

function sacarDoble(nodo) {
  nodo.anterior.siguiente = nodo.siguiente;
  nodo.siguiente.anterior = nodo.anterior;
}

function crearLRU(capacidad) {
  const raiz = crearDoble();
  const indice = new Map();
  function promover(nodo) {
    sacarDoble(nodo);
    indice.set(nodo.valor.clave, ponerAntes(raiz, nodo.valor));
  }
  return {
    leer(clave) {
      const nodo = indice.get(clave);
      if (!nodo) return { acierto: false, valor: null };
      promover(nodo);
      return { acierto: true, valor: nodo.valor.valor };
    },
    guardar(clave, valor) {
      if (capacidad === 0) return;
      const nodo = indice.get(clave);
      if (nodo) {
        nodo.valor.valor = valor;
        promover(nodo);
        return;
      }
      if (indice.size === capacidad) {
        const expulsado = raiz.siguiente;
        sacarDoble(expulsado);
        indice.delete(expulsado.valor.clave);
      }
      indice.set(clave, ponerAntes(raiz, { clave, valor }));
    },
    orden() {
      const claves = [];
      for (let nodo = raiz.siguiente; nodo !== raiz; nodo = nodo.siguiente)
        claves.push(nodo.valor.clave);
      return claves;
    },
  };
}

function tablaPrefijos(patron) {
  const pi = Array(patron.length).fill(0);
  let largo = 0;
  for (let i = 1; i < patron.length; i++) {
    while (largo && patron[i] !== patron[largo]) largo = pi[largo - 1];
    if (patron[i] === patron[largo]) largo++;
    pi[i] = largo;
  }
  return pi;
}

function buscarKMP(texto, patron) {
  if (!patron.length)
    return Array.from({ length: texto.length + 1 }, (_, i) => i);
  const pi = tablaPrefijos(patron);
  const indices = [];
  let largo = 0;
  for (let i = 0; i < texto.length; i++) {
    while (largo && texto[i] !== patron[largo]) largo = pi[largo - 1];
    if (texto[i] === patron[largo]) largo++;
    if (largo === patron.length) {
      indices.push(i - patron.length + 1);
      largo = pi[largo - 1];
    }
  }
  return indices;
}

function canonizarNombre(texto) {
  return texto.trim().toLowerCase().normalize("NFC");
}

function indiceDeNombres(estaciones) {
  const porNombre = new Map();
  for (const [codigo, nombre] of estaciones) {
    const clave = canonizarNombre(nombre);
    if (!porNombre.has(clave)) porNombre.set(clave, []);
    porNombre.get(clave).push(codigo);
  }
  return porNombre;
}

function catalogoTesla(estaciones, acciones, capacidad) {
  const nombres = indiceDeNombres(estaciones);
  const cache = crearLRU(capacidad);
  const historia = [];
  const respuestas = [];
  for (const [modo, consulta] of acciones) {
    if (modo === "deshacer") {
      respuestas.push(historia.pop() ?? null);
      continue;
    }
    const clave = canonizarNombre(consulta);
    const claveCache = JSON.stringify([modo, clave]);
    const previa = cache.leer(claveCache);
    let codigos = previa.valor;
    if (!previa.acierto) {
      if (clave === "") codigos = [];
      else if (modo === "exacta") codigos = nombres.get(clave) ?? [];
      else {
        const aceptados = new Set();
        for (const nombre of nombres.keys()) {
          if (buscarKMP(nombre, clave).length) aceptados.add(nombre);
        }
        codigos = estaciones
          .filter(([, nombre]) => aceptados.has(canonizarNombre(nombre)))
          .map(([codigo]) => codigo);
      }
      cache.guardar(claveCache, codigos);
    }
    historia.push({ modo, clave, codigos });
    respuestas.push({ acierto: previa.acierto, codigos });
  }
  return { respuestas, historia };
}

function limiteHorario(datos, hora, despues = false) {
  let inicio = 0;
  let fin = datos.length;
  while (inicio < fin) {
    const medio = inicio + Math.floor((fin - inicio) / 2);
    const minuto = datos[medio];
    if (minuto < hora || (despues && minuto === hora)) inicio = medio + 1;
    else fin = medio;
  }
  return inicio;
}

function mezclarHorarios(a, b) {
  const salida = [];
  let i = 0;
  let j = 0;
  while (i < a.length && j < b.length) {
    if (a[i][0] <= b[j][0]) salida.push(a[i++]);
    else salida.push(b[j++]);
  }
  for (; i < a.length; i++) salida.push(a[i]);
  for (; j < b.length; j++) salida.push(b[j]);
  return salida;
}

function ordenarMezcla(registros) {
  if (registros.length < 2) return registros.slice();
  const medio = Math.floor(registros.length / 2);
  const izquierda = ordenarMezcla(registros.slice(0, medio));
  const derecha = ordenarMezcla(registros.slice(medio));
  return mezclarHorarios(izquierda, derecha);
}

function bajarMonticulo(datos, i, tamano, compara) {
  while (2 * i + 1 < tamano) {
    const izquierdo = 2 * i + 1;
    const derecho = izquierdo + 1;
    const hijo =
      derecho < tamano && compara(datos[derecho], datos[izquierdo]) < 0
        ? derecho
        : izquierdo;
    if (compara(datos[hijo], datos[i]) >= 0) return;
    [datos[i], datos[hijo]] = [datos[hijo], datos[i]];
    i = hijo;
  }
}

function construirMonticulo(datos, compara) {
  const copia = datos.slice();
  for (let i = Math.floor(copia.length / 2) - 1; i >= 0; i--)
    bajarMonticulo(copia, i, copia.length, compara);
  return copia;
}

function crearColaPrioridad(datos, compara) {
  const heap = construirMonticulo(datos, compara);
  return {
    tamano: () => heap.length,
    ver: () => heap[0] ?? null,
    agregar(valor) {
      heap.push(valor);
      let i = heap.length - 1;
      while (i > 0) {
        const padre = Math.floor((i - 1) / 2);
        if (compara(heap[i], heap[padre]) >= 0) break;
        [heap[i], heap[padre]] = [heap[padre], heap[i]];
        i = padre;
      }
    },
    extraer() {
      if (!heap.length) return null;
      const primero = heap[0];
      const ultimo = heap.pop();
      if (heap.length) {
        heap[0] = ultimo;
        bajarMonticulo(heap, 0, heap.length, compara);
      }
      return primero;
    },
  };
}

function agendaInicial(viajes) {
  return ordenarMezcla(viajes.map(([id, origen, salida]) => [salida, id]));
}

function simularLlegadas(viajes, hasta) {
  const eventos = viajes.map((viaje, i) => [viaje[2], i, i, 0]);
  const cola = crearColaPrioridad(
    eventos,
    (a, b) => a[0] - b[0] || a[1] - b[1],
  );
  const resultados = [];
  let alta = viajes.length;
  while (cola.tamano() && cola.ver()[0] <= hasta) {
    const [minuto, , i, parada] = cola.extraer();
    const [id, , , duraciones] = viajes[i];
    resultados.push([minuto, id, parada]);
    if (parada < duraciones.length) {
      const proximo = minuto + duraciones[parada];
      cola.agregar([proximo, alta++, i, parada + 1]);
    }
  }
  return resultados;
}

function servicioTesla(estaciones, consulta, viajes, desde, hasta) {
  const { respuestas } = catalogoTesla(estaciones, [["exacta", consulta]], 1);
  const codigos = respuestas[0].codigos;
  const origenes = new Set(codigos);
  const filtrados = viajes.filter(([, origen]) => origenes.has(origen));
  const horario = agendaInicial(filtrados);
  const posicion = limiteHorario(
    horario.map((registro) => registro[0]),
    desde,
  );
  return {
    codigos,
    horario,
    proxima: horario[posicion] ?? null,
    eventos: simularLlegadas(filtrados, hasta),
  };
}

function nodoArbol(clave, izq = null, der = null) {
  return { clave, izq, der };
}
function recorrerArbol(raiz) {
  const pre = [],
    inorden = [],
    post = [],
    hojas = [];
  function visitar(nodo) {
    if (nodo === null) return;
    const { clave, izq, der } = nodo;
    pre.push(clave);
    if (izq === null && der === null) hojas.push(clave);
    visitar(izq);
    inorden.push(clave);
    visitar(der);
    post.push(clave);
  }
  visitar(raiz);
  return { pre, inorden, post, hojas };
}

function porNiveles(raiz) {
  if (raiz === null) return [];
  const cola = [raiz];
  const niveles = [];
  let inicio = 0;
  while (inicio < cola.length) {
    const fin = cola.length;
    const nivel = [];
    while (inicio < fin) {
      const nodo = cola[inicio++];
      nivel.push(nodo.clave);
      if (nodo.izq !== null) cola.push(nodo.izq);
      if (nodo.der !== null) cola.push(nodo.der);
    }
    niveles.push(nivel);
  }
  return niveles;
}

function planoJerarquico(raiz) {
  const recorridos = recorrerArbol(raiz);
  const niveles = porNiveles(raiz);
  return { recorridos, niveles, profundidad: niveles.length - 1 };
}

function insertarBST(raiz, clave) {
  if (raiz === null) return nodoArbol(clave);
  if (clave === raiz.clave) return raiz;
  if (clave < raiz.clave)
    return nodoArbol(raiz.clave, insertarBST(raiz.izq, clave), raiz.der);
  return nodoArbol(raiz.clave, raiz.izq, insertarBST(raiz.der, clave));
}
function construirBST(claves) {
  let raiz = null;
  for (const clave of claves) raiz = insertarBST(raiz, clave);
  return raiz;
}

function borrarBST(raiz, clave) {
  if (raiz === null) return null;
  if (clave < raiz.clave)
    return nodoArbol(raiz.clave, borrarBST(raiz.izq, clave), raiz.der);
  if (clave > raiz.clave)
    return nodoArbol(raiz.clave, raiz.izq, borrarBST(raiz.der, clave));
  if (raiz.izq === null) return raiz.der;
  if (raiz.der === null) return raiz.izq;
  let sucesor = raiz.der;
  while (sucesor.izq !== null) sucesor = sucesor.izq;
  return nodoArbol(sucesor.clave, raiz.izq, borrarBST(raiz.der, sucesor.clave));
}
function editarBST(claves, bajas) {
  let raiz = construirBST(claves);
  for (const clave of bajas) raiz = borrarBST(raiz, clave);
  return raiz;
}

function agendaDeInspecciones(claves, bajas) {
  const raiz = editarBST(claves, bajas);
  return { claves: recorrerArbol(raiz).inorden, raiz: raiz?.clave ?? null };
}

function alturaArbol(raiz) {
  return raiz === null
    ? 0
    : 1 + Math.max(alturaArbol(raiz.izq), alturaArbol(raiz.der));
}
function estadoAltura(raiz) {
  if (raiz === null) return { altura: 0, factor: 0 };
  const izq = alturaArbol(raiz.izq);
  const der = alturaArbol(raiz.der);
  return { altura: 1 + Math.max(izq, der), factor: izq - der };
}

function altoAVL(nodo) {
  return nodo?.altura ?? 0;
}
function nodoAVL(clave, izq = null, der = null) {
  return { clave, izq, der, altura: 1 + Math.max(altoAVL(izq), altoAVL(der)) };
}
function factorAVL(nodo) {
  return nodo === null ? 0 : altoAVL(nodo.izq) - altoAVL(nodo.der);
}
function girarDerecha(raiz) {
  const nueva = raiz.izq;
  return nodoAVL(
    nueva.clave,
    nueva.izq,
    nodoAVL(raiz.clave, nueva.der, raiz.der),
  );
}
function girarIzquierda(raiz) {
  const nueva = raiz.der;
  return nodoAVL(
    nueva.clave,
    nodoAVL(raiz.clave, raiz.izq, nueva.izq),
    nueva.der,
  );
}
function equilibrarAVL(nodo) {
  const factor = factorAVL(nodo);
  if (factor > 1) {
    if (factorAVL(nodo.izq) < 0)
      nodo = nodoAVL(nodo.clave, girarIzquierda(nodo.izq), nodo.der);
    return girarDerecha(nodo);
  }
  if (factor < -1) {
    if (factorAVL(nodo.der) > 0)
      nodo = nodoAVL(nodo.clave, nodo.izq, girarDerecha(nodo.der));
    return girarIzquierda(nodo);
  }
  return nodo;
}
function insertarAVL(nodo, clave) {
  if (nodo === null) return nodoAVL(clave);
  if (clave === nodo.clave) return nodo;
  if (clave < nodo.clave)
    return equilibrarAVL(
      nodoAVL(nodo.clave, insertarAVL(nodo.izq, clave), nodo.der),
    );
  return equilibrarAVL(
    nodoAVL(nodo.clave, nodo.izq, insertarAVL(nodo.der, clave)),
  );
}
function construirAVL(claves) {
  let raiz = null;
  for (const clave of claves) raiz = insertarAVL(raiz, clave);
  return raiz;
}

function borrarAVL(nodo, clave) {
  if (nodo === null) return null;
  if (clave < nodo.clave)
    return equilibrarAVL(
      nodoAVL(nodo.clave, borrarAVL(nodo.izq, clave), nodo.der),
    );
  if (clave > nodo.clave)
    return equilibrarAVL(
      nodoAVL(nodo.clave, nodo.izq, borrarAVL(nodo.der, clave)),
    );
  if (nodo.izq === null) return nodo.der;
  if (nodo.der === null) return nodo.izq;
  let sucesor = nodo.der;
  while (sucesor.izq !== null) sucesor = sucesor.izq;
  return equilibrarAVL(
    nodoAVL(sucesor.clave, nodo.izq, borrarAVL(nodo.der, sucesor.clave)),
  );
}
function agendaEquilibrada(claves, bajas) {
  let raiz = construirAVL(claves);
  for (const clave of bajas) raiz = borrarAVL(raiz, clave);
  return {
    raiz: raiz?.clave ?? null,
    altura: altoAVL(raiz),
    claves: recorrerArbol(raiz).inorden,
  };
}

function crearTrie(registros) {
  const raiz = { hijos: new Map(), registros: [] };
  for (const [codigo, nombre] of registros) {
    const clave = canonizarNombre(nombre);
    let nodo = raiz;
    for (let i = 0; i < clave.length; i++) {
      const unidad = clave[i];
      if (!nodo.hijos.has(unidad))
        nodo.hijos.set(unidad, { hijos: new Map(), registros: [] });
      nodo = nodo.hijos.get(unidad);
    }
    nodo.registros.push([codigo, nombre]);
  }
  return raiz;
}
function buscarPrefijo(raiz, clave) {
  let nodo = raiz;
  for (let i = 0; i < clave.length; i++) {
    nodo = nodo.hijos.get(clave[i]);
    if (!nodo) return null;
  }
  return nodo;
}
function coincidenciaTrie(registros, texto) {
  const nodo = buscarPrefijo(crearTrie(registros), canonizarNombre(texto));
  return {
    existe: nodo !== null,
    completos: nodo?.registros.map(([codigo]) => codigo) ?? [],
  };
}

function sugerenciasTrie(raiz, texto, limite) {
  const inicio = buscarPrefijo(raiz, canonizarNombre(texto));
  if (inicio === null || limite === 0) return [];
  const salida = [];
  function visitar(nodo) {
    for (const registro of nodo.registros) {
      salida.push(registro);
      if (salida.length === limite) return;
    }
    for (const unidad of Array.from(nodo.hijos.keys()).sort()) {
      visitar(nodo.hijos.get(unidad));
      if (salida.length === limite) return;
    }
  }
  visitar(inicio);
  return salida;
}
function autocompletar(registros, texto, limite) {
  return sugerenciasTrie(crearTrie(registros), texto, limite);
}

function panelDeNombres(registros, texto, limite) {
  const sugerencias = autocompletar(registros, texto, limite);
  return {
    prefijo: canonizarNombre(texto),
    sugerencias,
    total: sugerencias.length,
  };
}

function crearUnionFind(cantidad) {
  const padres = Array.from({ length: cantidad }, (_, i) => i);
  const rangos = Array(cantidad).fill(0);
  let grupos = cantidad;
  function representante(i) {
    let raiz = i;
    while (padres[raiz] !== raiz) raiz = padres[raiz];
    while (padres[i] !== i) {
      const anterior = padres[i];
      padres[i] = raiz;
      i = anterior;
    }
    return raiz;
  }
  return {
    representante,
    grupos: () => grupos,
    conectar(a, b) {
      let x = representante(a);
      let y = representante(b);
      if (x === y) return false;
      if (rangos[x] < rangos[y]) [x, y] = [y, x];
      padres[y] = x;
      if (rangos[x] === rangos[y]) rangos[x]++;
      grupos--;
      return true;
    },
    conexiones: () => padres.slice(),
  };
}
function registrarVinculos(cantidad, pares) {
  const grupos = crearUnionFind(cantidad);
  for (const [a, b] of pares) grupos.conectar(a, b);
  return { padres: grupos.conexiones(), grupos: grupos.grupos() };
}

function inspeccionarRepresentantes(cantidad, pares, consultas) {
  const uf = crearUnionFind(cantidad);
  for (const [a, b] of pares) uf.conectar(a, b);
  const respuestas = consultas.map(uf.representante);
  return { respuestas, padres: uf.conexiones() };
}

function gruposDeAndenes(cantidad, acciones) {
  const uf = crearUnionFind(cantidad);
  const respuestas = acciones.map(([tipo, a, b]) =>
    tipo === "unir"
      ? uf.conectar(a, b)
      : uf.representante(a) === uf.representante(b),
  );
  return { respuestas, grupos: uf.grupos() };
}

function saltoFenwick(i) {
  return i & -i;
}
function crearFenwick(datos) {
  const parciales = Array(datos.length + 1).fill(0);
  function sumar(indice, delta) {
    for (let i = indice + 1; i < parciales.length; i += saltoFenwick(i))
      parciales[i] += delta;
  }
  function prefijo(hasta) {
    let total = 0;
    for (let i = hasta; i > 0; i -= saltoFenwick(i)) total += parciales[i];
    return total;
  }
  datos.forEach((valor, i) => sumar(i, valor));
  return {
    sumar,
    prefijo,
    rango: (inicio, fin) => prefijo(fin) - prefijo(inicio),
  };
}
function prefijosFenwick(datos, limites) {
  const tabla = crearFenwick(datos);
  return limites.map(tabla.prefijo);
}

function operarFenwick(datos, operaciones) {
  const tabla = crearFenwick(datos);
  const respuestas = [];
  for (const [tipo, a, b] of operaciones) {
    if (tipo === "sumar") tabla.sumar(a, b);
    else respuestas.push(tabla.rango(a, b));
  }
  return respuestas;
}

function aforoPuntual(datos, operaciones) {
  const respuestas = operarFenwick(datos, [
    ...operaciones,
    ["rango", 0, datos.length],
  ]);
  const total = respuestas.pop();
  return { respuestas, total };
}

function combinarSegmentos(a, b) {
  if (a.minimo === null) return b;
  if (b.minimo === null) return a;
  return { suma: a.suma + b.suma, minimo: Math.min(a.minimo, b.minimo) };
}
function crearSegmentos(datos, inicio = 0, fin = datos.length) {
  if (inicio === fin) return null;
  if (fin - inicio === 1) {
    return {
      inicio,
      fin,
      suma: datos[inicio],
      minimo: datos[inicio],
      pendiente: 0,
      izq: null,
      der: null,
    };
  }
  const medio = inicio + Math.floor((fin - inicio) / 2);
  const izq = crearSegmentos(datos, inicio, medio);
  const der = crearSegmentos(datos, medio, fin);
  return {
    inicio,
    fin,
    ...combinarSegmentos(izq, der),
    pendiente: 0,
    izq,
    der,
  };
}
function resumirRaiz(datos) {
  const raiz = crearSegmentos(datos);
  return raiz
    ? { suma: raiz.suma, minimo: raiz.minimo }
    : { suma: 0, minimo: null };
}

function aplicarSegmento(nodo, delta) {
  nodo.suma += (nodo.fin - nodo.inicio) * delta;
  nodo.minimo += delta;
  nodo.pendiente += delta;
}
function propagarSegmento(nodo) {
  if (nodo.izq === null || nodo.pendiente === 0) return;
  aplicarSegmento(nodo.izq, nodo.pendiente);
  aplicarSegmento(nodo.der, nodo.pendiente);
  nodo.pendiente = 0;
}
function sumarSegmento(nodo, inicio, fin, delta) {
  if (
    nodo === null ||
    inicio >= fin ||
    fin <= nodo.inicio ||
    nodo.fin <= inicio
  )
    return;
  if (inicio <= nodo.inicio && nodo.fin <= fin) {
    aplicarSegmento(nodo, delta);
    return;
  }
  propagarSegmento(nodo);
  sumarSegmento(nodo.izq, inicio, fin, delta);
  sumarSegmento(nodo.der, inicio, fin, delta);
  const datos = combinarSegmentos(nodo.izq, nodo.der);
  nodo.suma = datos.suma;
  nodo.minimo = datos.minimo;
}
function leerSegmento(nodo, inicio, fin) {
  if (
    nodo === null ||
    inicio >= fin ||
    fin <= nodo.inicio ||
    nodo.fin <= inicio
  )
    return { suma: 0, minimo: null };
  if (inicio <= nodo.inicio && nodo.fin <= fin)
    return { suma: nodo.suma, minimo: nodo.minimo };
  propagarSegmento(nodo);
  return combinarSegmentos(
    leerSegmento(nodo.izq, inicio, fin),
    leerSegmento(nodo.der, inicio, fin),
  );
}
function prepararSegmentos(datos) {
  const raiz = crearSegmentos(datos);
  return {
    sumar: (inicio, fin, delta) => sumarSegmento(raiz, inicio, fin, delta),
    medir: (inicio, fin) => leerSegmento(raiz, inicio, fin),
  };
}
function operarSegmentos(datos, acciones) {
  const indice = prepararSegmentos(datos);
  const respuestas = [];
  for (const [tipo, inicio, fin, delta] of acciones) {
    if (tipo === "sumar") indice.sumar(inicio, fin, delta);
    else respuestas.push(indice.medir(inicio, fin));
  }
  return respuestas;
}

function reporteSegmentado(datos, acciones) {
  const respuestas = operarSegmentos(datos, [
    ...acciones,
    ["medir", 0, datos.length],
  ]);
  const final = respuestas.pop();
  return { respuestas, final };
}

function indiceDeTelemetria(lecturas) {
  return new Map(
    lecturas.map(([codigo, datos]) => [codigo, prepararSegmentos(datos)]),
  );
}
function medirEstacion(lecturas, consultas) {
  const indice = indiceDeTelemetria(lecturas);
  return consultas.map(
    ([codigo, inicio, fin]) => indice.get(codigo)?.medir(inicio, fin) ?? null,
  );
}

function consultarTablero(nombres, conteos, prefijo, inicio, fin, limite) {
  return sugerenciasTrie(nombres, prefijo, limite).map(([codigo, nombre]) => ({
    codigo,
    nombre,
    medicion: conteos.get(codigo)?.medir(inicio, fin) ?? null,
  }));
}
function sugerirConAforo(estaciones, lecturas, prefijo, inicio, fin, limite) {
