  const conteos = indiceDeTelemetria(lecturas);
  const respuestas = [];
  for (const [tipo, clave, inicio, fin, valor] of operaciones) {
    if (tipo === "ajustar") conteos.get(clave)?.sumar(inicio, fin, valor);
